-- Generated by scripts/build_tests.py; edit generator and regenerate.
-- Run after 01_schema.sql in a dedicated client-selected test database:
-- mariadb --database=two_clocks_cabd_verify_UNIQUE < tests/01_schema_smoke.sql
-- Do not use --force. No schema reload, COMMIT, or business-table DDL here.
-- All fixture DML is rolled back, including on unexpected errors.
-- AUTO_INCREMENT counters can advance despite rollback. Helper DDL commits implicitly;
-- invoke from a fresh connection with no existing transaction.
-- Requirements map: 01 metadata; 02 clock; 03 registry; 04 insert guards;
-- 05 checks/FKs; 06 protected columns; 07 closure; 08 closed/delete;
-- 09 identity; 10 I1; 11 I2; 12 I3; 13 five-row story/boundaries;
-- 14 E3/E4/E5/E8/E9 and atomic rollback; 15 query parameters.
SET @smoke_old_mode=@@SESSION.sql_mode, @smoke_old_zone=@@SESSION.time_zone;
SET @smoke_old_sim=@sim_now, @smoke_old_write=@write_tx_id;
SET SESSION time_zone='+00:00';
SET SESSION sql_mode='STRICT_ALL_TABLES,NO_ZERO_DATE,NO_ZERO_IN_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DROP PROCEDURE IF EXISTS smoke_run;
DROP PROCEDURE IF EXISTS smoke_expect_error;
DROP PROCEDURE IF EXISTS smoke_assert;
DELIMITER $$
CREATE PROCEDURE smoke_assert(IN p_ok BOOLEAN, IN p_label VARCHAR(200))
BEGIN
 DECLARE v_msg VARCHAR(255);
 IF p_ok IS NULL OR NOT p_ok THEN
  SET v_msg=CONCAT('SMOKE_ASSERT: ',p_label);
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=v_msg;
 END IF;
 SET @smoke_assertions=COALESCE(@smoke_assertions,0)+1;
 SELECT 'PASS' AS verdict, p_label AS assertion;
END$$
CREATE PROCEDURE smoke_expect_error(IN p_sql TEXT, IN p_errno INT, IN p_fragment VARCHAR(128))
BEGIN
 DECLARE v_errno INT DEFAULT 0;
 DECLARE v_message TEXT DEFAULT '';
 DECLARE v_prepared BOOLEAN DEFAULT FALSE;
 DECLARE v_failure VARCHAR(255);
 BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
   GET DIAGNOSTICS CONDITION 1 v_errno=MYSQL_ERRNO, v_message=MESSAGE_TEXT;
  SET @smoke_sql=p_sql;
  PREPARE smoke_stmt FROM @smoke_sql;
  SET v_prepared=TRUE;
  EXECUTE smoke_stmt;
 END;
 IF v_prepared THEN DEALLOCATE PREPARE smoke_stmt; END IF;
 IF v_errno <> p_errno OR LOCATE(p_fragment,v_message)=0 THEN
  SET v_failure=LEFT(CONCAT('SMOKE_EXPECT: wanted ',p_errno,'/',p_fragment,
    '; got ',v_errno,'/',v_message,'; SQL=',p_sql),255);
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=v_failure;
 END IF;
 SET @smoke_assertions=COALESCE(@smoke_assertions,0)+1;
 SELECT 'PASS expected rejection' AS verdict, v_errno AS actual_errno, v_message AS actual_message, p_sql AS rejected_sql;
END$$
CREATE PROCEDURE smoke_run()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  SET @sim_now=@smoke_old_sim, @write_tx_id=@smoke_old_write;
  SET SESSION sql_mode=@smoke_old_mode;
  SET SESSION time_zone=@smoke_old_zone;
  RESIGNAL;
 END;
 SET @smoke_assertions=0;
