-- 02. Clock: canonical precision, invalid calendar, garbage, future, NULL/unset

SET @sim_now='2026-02-30 10:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2025-02-29 10:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-00-01 10:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-01-00 10:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='garbage';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-01-01T00:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-01-01 00:00:00.1234567';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-01-01 25:00:00';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='9999-12-31 23:59:59.999999';

CALL smoke_expect_error('SET @clock_result=fn_effective_time()', 1644, 'TC_CLOCK:');

SET @sim_now='2026-01-02 09:00:00';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 0');

SET @sim_now='2026-01-02 09:00:00.1';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 1');

SET @sim_now='2026-01-02 09:00:00.12';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 2');

SET @sim_now='2026-01-02 09:00:00.123';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 3');

SET @sim_now='2026-01-02 09:00:00.1234';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 4');

SET @sim_now='2026-01-02 09:00:00.12345';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 5');

SET @sim_now='2026-01-02 09:00:00.123456';

CALL smoke_assert((fn_effective_time()=CAST(@sim_now AS DATETIME(6))), 'clock precision 6');

SET @sim_now=NULL; SET @clock_before=UTC_TIMESTAMP(6); SET @clock_result=fn_effective_time();

CALL smoke_assert((@clock_before<=@clock_result AND @clock_result<=UTC_TIMESTAMP(6)), 'NULL/unset clock uses UTC');

